protected void btnConcat_Click(object sender, EventArgs e)
{
    lblResult.Text = txtString1.Text + " " + txtString2.Text;
}

protected void btnCalculate_Click(object sender, EventArgs e)
{
    double a = Convert.ToDouble(txtA.Text);
    double b = Convert.ToDouble(txtB.Text);
    double result = Math.Pow(a, b);
    lblResult.Text = "Result: " + result;
}

protected void btnCalculate_Click(object sender, EventArgs e)
{
    int m1 = Convert.ToInt32(txtSubject1.Text);
    int m2 = Convert.ToInt32(txtSubject2.Text);
    int m3 = Convert.ToInt32(txtSubject3.Text);
    int total = m1 + m2 + m3;
    double avg = total / 3.0;
    lblResult.Text = $"Total: {total}, Average: {avg:F2}";
}

protected void btnSubmit_Click(object sender, EventArgs e)
{
    lblOutput.Text = $"Thank you {txtName.Text} ({txtEmail.Text}) for your feedback: {txtMessage.Text}";
}

protected void btnUpload_Click(object sender, EventArgs e)
{
    if (fileUpload.HasFile)
    {
        string fileName = fileUpload.FileName;
        fileUpload.SaveAs(Server.MapPath("~/Uploads/" + fileName));
        lblMessage.Text = "File uploaded successfully: " + fileName;
    }
    else
    {
        lblMessage.Text = "Please select a file to upload.";
    }
}
